const input = $input.item.json;

const prompts = {
  expansion: `Mitch is considering expansion. Analyze:
Current location: ${input.current_location || 'Bucharest'}
Options: ${input.expansion_options || 'Cluj-Napoca, Brasov, Timisoara'}
Budget: ${input.budget || '50,000 RON'}
Current revenue: ${input.current_revenue || '20,000 RON/month'}

Provide:
1. Recommended city with justification
2. Market opportunity analysis
3. Competition assessment
4. Budget allocation
5. Timeline and milestones
6. Risk mitigation strategies`,

  pricing: `Analyze pricing strategy for Mitch:
Current items: ${input.current_items || 'Sarmale burrito 25 RON, Mici tacos 20 RON'}
Cost per item: ${input.costs || '8-12 RON'}
Competitors pricing: ${input.competitor_prices || '15-35 RON similar items'}
Target margin: ${input.target_margin || '60%'}

Recommend:
1. Optimal pricing for each item
2. Premium vs value positioning
3. Combo deals
4. Seasonal pricing adjustments
5. Upselling strategies`,

  marketing_budget: `Plan marketing budget for Mitch:
Total budget: ${input.budget || '5,000 RON/month'}
Goals: ${input.goals || 'Increase awareness, drive foot traffic'}
Current channels: ${input.current_channels || 'Instagram, Facebook'}

Allocate budget across:
1. Social media ads
2. Influencer partnerships
3. Local events/sponsorships
4. Content creation
5. Print materials
Justify each allocation with expected ROI`,

  menu_optimization: `Analyze Mitch menu performance:
Best sellers: ${input.best_sellers || 'Unknown'}
Slow movers: ${input.slow_movers || 'Unknown'}
Margins: ${input.margins || 'Unknown'}
Customer feedback: ${input.feedback || 'None provided'}

Recommend:
1. Items to keep/promote
2. Items to modify or remove
3. New items to test
4. Menu size optimization
5. Pricing adjustments`,

  partnership: `Evaluate partnership opportunity:
Partner type: ${input.partner_type || 'Food delivery app'}
Proposed terms: ${input.terms || 'Not specified'}
Expected volume: ${input.volume || 'Not specified'}

Analyze:
1. Financial impact
2. Brand alignment
3. Operational requirements
4. Risks and benefits
5. Negotiation points
6. Decision recommendation`
};

const selectedPrompt = prompts[input.strategy_type || 'expansion'];

return [{
  json: {
    prompt: selectedPrompt,
    strategy_type: input.strategy_type,
    context: input
  }
}];

const aiResponse = $input.item.json;
const context = $node['Build Strategy Prompt'].json.context;

return [{
  json: {
    strategy_type: context.strategy_type,
    analysis: aiResponse.results[0].response,
    timestamp: new Date().toISOString(),
    next_steps: "Review this analysis with your team and create an action plan",
    disclaimer: "This is AI-generated advice. Consult with business advisors for major decisions."
  }
}];
